-- 60 demo listings; idempotent, additive, and clearly marked as synthetic.
-- FIRST deploy public/demo-listings/*.png to listoqasa.com and run migration 205.
-- RUN: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -v owner_id=UUID -v team_id=UUID -f import_60_demo.sql
-- owner_id and team_id must identify an authorized existing account/team.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('listoqasa-60-demo-import'));
CREATE TEMP TABLE _demo_owner (owner_id uuid, team_id uuid) ON COMMIT DROP;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM _demo_owner o JOIN users u ON u.id=o.owner_id JOIN teams t ON t.id=o.team_id) THEN RAISE EXCEPTION 'Invalid owner/team'; END IF; END $$;
CREATE TEMP TABLE _demo_records (external_id text PRIMARY KEY, payload jsonb) ON COMMIT DROP;

-- Only update rows originally created by this import; never overwrite existing genuine properties.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM _demo_records r JOIN listoqasa_sample_imports i ON i.external_id=r.external_id JOIN properties p ON p.id=i.property_id WHERE p.status <> 'published' OR NOT (i.payload->>'source' = 'synthetic_preview')) THEN RAISE EXCEPTION 'ID collision with non-demo listing'; END IF; END $$;
SELECT (r.payload->>'title') || ' [SAMPLE / DEMO]',
       (r.payload->>'description') || E'\n\n' || (r.payload->>'public_disclosure') ||
       CASE WHEN r.payload->>'price_basis'='reference_starting_price' THEN E'\nStarting reference price per unit; not the total development price.' WHEN r.payload->>'price_basis'='monthly' THEN E'\nRental price: USD per month.' ELSE '' END,
       r.payload->>'city',r.payload->>'area','Ecuador',(r.payload->>'price_usd')::numeric,r.payload->>'listing_type',
       'published','marketplace',r.payload->>'property_type',round((r.payload->>'area_m2')::numeric*10.7639104167)::integer,
       'https://listoqasa.com/demo-listings/' || r.external_id || '.png',o.owner_id,o.team_id,NOW()
FROM _demo_records r CROSS JOIN _demo_owner o
WHERE NOT EXISTS(SELECT 1 FROM listoqasa_sample_imports i WHERE i.external_id=r.external_id);
-- Newly inserted properties are matched by their unique demo title; guard against ambiguous matches.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM _demo_records r LEFT JOIN listoqasa_sample_imports i ON i.external_id=r.external_id WHERE i.external_id IS NULL AND (SELECT count(*) FROM properties p WHERE p.title=(r.payload->>'title') || ' [SAMPLE / DEMO]' AND p.created_by=(SELECT owner_id FROM _demo_owner)) <> 1) THEN RAISE EXCEPTION 'Ambiguous demo property title'; END IF; END $$;
SELECT r.external_id,p.id,r.payload->>'city',r.payload FROM _demo_records r JOIN properties p ON p.title=(r.payload->>'title') || ' [SAMPLE / DEMO]' AND p.created_by=(SELECT owner_id FROM _demo_owner)
WHERE NOT EXISTS (SELECT 1 FROM listoqasa_sample_imports i WHERE i.external_id=r.external_id);
SELECT i.property_id,'https://listoqasa.com/demo-listings/' || i.external_id || '.png','image',true,0
FROM listoqasa_sample_imports i JOIN _demo_records r ON r.external_id=i.external_id
WHERE NOT EXISTS(SELECT 1 FROM property_media m WHERE m.property_id=i.property_id AND m.url='https://listoqasa.com/demo-listings/' || i.external_id || '.png');
SELECT i.external_id,0,m.url,m.id FROM listoqasa_sample_imports i JOIN _demo_records r ON r.external_id=i.external_id JOIN property_media m ON m.property_id=i.property_id AND m.url='https://listoqasa.com/demo-listings/' || i.external_id || '.png'
ON CONFLICT(external_id,image_index) DO NOTHING;
COMMIT;
SELECT i.payload->>'category' AS category,count(*) AS imported FROM listoqasa_sample_imports i WHERE i.external_id LIKE 'COM-%' OR i.external_id LIKE 'PRO-%' GROUP BY 1;
